// GLSL shader code for the procedural Earth. Ported unchanged from the approved design mock-up.
// Everything is generated by maths: no image textures are downloaded, and nothing here is real data.

/** Shared vertex shader for the Earth, clouds and atmosphere shells. */
export const PLANET_VERTEX = `
varying vec3 vP,vN,vW;
void main(){vP=normalize(position);vN=normalize(mat3(modelMatrix)*normal);vW=(modelMatrix*vec4(position,1.)).xyz;gl_Position=projectionMatrix*viewMatrix*vec4(vW,1.);}
`;

/** Value noise. "OCT" is replaced with the number of noise layers (fewer on phones). */
export const NOISE_GLSL = `
float h(vec3 p){p=fract(p*.3183099+.1);p*=17.;return fract(p.x*p.y*p.z*(p.x+p.y+p.z));}
float n(vec3 x){vec3 i=floor(x),f=fract(x);f=f*f*(3.-2.*f);
return mix(mix(mix(h(i),h(i+vec3(1,0,0)),f.x),mix(h(i+vec3(0,1,0)),h(i+vec3(1,1,0)),f.x),f.y),
mix(mix(h(i+vec3(0,0,1)),h(i+vec3(1,0,1)),f.x),mix(h(i+vec3(0,1,1)),h(i+vec3(1,1,1)),f.x),f.y),f.z);}
float fbm(vec3 p){float a=.5,s=0.;for(int i=0;i<OCT;i++){s+=a*n(p);p=p*2.03+1.7;a*=.5;}return s;}
`;

export const EARTH_FRAGMENT = `
uniform vec3 uSun;varying vec3 vP,vN,vW;
void main(){
 vec3 p=vP,N=normalize(vN),V=normalize(cameraPosition-vW);
 float e=fbm(p*1.7+4.2),lat=abs(p.y),dry=fbm(p*3.+9.),rough=fbm(p*9.);
 float land=smoothstep(.5,.522,e);
 vec3 lc=mix(vec3(.08,.24,.08),vec3(.6,.5,.3),smoothstep(.42,.6,dry));
 lc=mix(lc,vec3(.3,.36,.2),smoothstep(.55,.8,lat)*.7);
 lc=mix(lc,vec3(.36,.31,.27),smoothstep(.57,.7,e)*.8);
 lc*=.7+.6*rough;
 float snow=max(smoothstep(.8,.9,lat+(rough-.5)*.15),smoothstep(.68,.76,e));
 lc=mix(lc,vec3(.93,.96,1.),snow);
 vec3 oc=mix(vec3(.01,.045,.15),vec3(.05,.25,.45),smoothstep(.32,.5,e));
 float ice=smoothstep(.88,.94,lat+(rough-.5)*.1);
 vec3 col=mix(oc,lc,land);col=mix(col,vec3(.9,.95,1.),ice*(1.-land));
 float d=dot(N,uSun),diff=max(d,0.),term=smoothstep(-.05,.3,d);
 float sp=pow(max(dot(reflect(-uSun,N),V),0.),70.)*(1.-land)*(1.-ice);
 vec3 c=col*diff*1.25+vec3(1.,.95,.85)*sp*diff*.9;
 c+=col*vec3(.03,.05,.09);
 float city=land*smoothstep(.66,.74,fbm(p*14.))*smoothstep(.5,.62,fbm(p*2.+2.))*(1.-term)*(1.-smoothstep(.7,.9,lat));
 c+=vec3(1.,.65,.25)*city*.9;
 float fr=pow(1.-max(dot(N,V),0.),3.);
 c+=vec3(.25,.5,1.)*fr*(smoothstep(-.25,.45,d)*.75+.06);
 c+=vec3(.9,.4,.15)*exp(-pow(d*5.,2.))*.05;
 gl_FragColor=vec4(pow(c,vec3(.56)),1.);
}
`;

export const CLOUD_FRAGMENT = `
uniform vec3 uSun;varying vec3 vP,vN,vW;
void main(){
 vec3 N=normalize(vN);
 float c=fbm(vP*2.4+vec3(1.,7.,3.)),c2=fbm(vP*6.);
 float a=smoothstep(.5,.72,c)*(.55+.6*c2);
 float l=max(dot(N,uSun),0.)*1.15+.025;
 gl_FragColor=vec4(pow(vec3(l),vec3(.56))*vec3(.97,.98,1.),clamp(a*.9,0.,1.));
}
`;

export const ATMOSPHERE_FRAGMENT = `
uniform vec3 uSun;varying vec3 vP,vN,vW;
void main(){
 vec3 N=normalize(vN),V=normalize(cameraPosition-vW);
 float f=pow(1.-max(dot(N,V),0.),2.6);
 float s=smoothstep(-.5,.6,dot(N,uSun))*.9+.1;
 gl_FragColor=vec4(vec3(.22,.55,1.),clamp(f*s*1.1,0.,1.));
}
`;
